// Counts comment lines that tools read as directives (doctest `// =>`,
// `// jet:line`, `// canvas:…`, `// jet-ffi-…=`, `// runtime-init:`,
// `// generated by:`, `// expect…`) in tracked .jet files (read-only).
// usage: [OUT=file.json] node directive-census.mjs <repo>
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const repo = process.argv[2];
const env = { ...process.env };
delete env.GIT_INDEX_FILE;
const files = execFileSync('git', ['-C', repo, 'ls-files', '-z', '--', '*.jet'], { env, maxBuffer: 1 << 28 }).toString().split('\0').filter(Boolean);
const kinds = {
  doctestExpect: /\/\/ =>/,
  jetLine: /\/\/ jet:line/,
  canvas: /\/\/ canvas:/,
  ffi: /\/\/ jet-ffi-[a-z]+=/,
  runtime: /\/\/ runtime-(init|fini):/,
  generated: /\/\/ generated by:/,
  expectDirective: /^\s*\/\/ ?(expect|EXPECT|error|ERROR|check|CHECK)[-_:A-Za-z]*:/,
};
const counts = Object.fromEntries(Object.keys(kinds).map((k) => [k, 0]));
const samples = Object.fromEntries(Object.keys(kinds).map((k) => [k, []]));
for (const f of files) {
  let src;
  try { src = readFileSync(`${repo}/${f}`, 'utf8'); } catch { continue; }
  src.split('\n').forEach((line, i) => {
    for (const [k, re] of Object.entries(kinds)) {
      if (re.test(line)) { counts[k]++; if (samples[k].length < 3) samples[k].push(`${f}:${i + 1}: ${line.trim().slice(0, 90)}`); }
    }
  });
}
const out = { counts, samples };
if (process.env.OUT) writeFileSync(process.env.OUT, JSON.stringify(out, null, 1) + '\n');
console.log(JSON.stringify(out, null, 1));
